def oracleScore (θ : Schedule V) (z : Assign V) : ℝ :=
  (2 / (Fintype.card V : ℝ)) * ∑ i,
    potentialOutcome θ i z * (signOf (z i) + ∑ j ∈ inNbhd θ i, signOf (z j))

