def blockMixtureLawOf (D : Measure (Assign (Fin n) × Audit (Fin n))) (σ : Bool) (h : ℝ) :
    Measure (Record (Fin n)) := mixtureLaw D (blockParamLaw B d) (blockSchedule n B d σ h)

